    def self.material(model, name)
      m = model.materials[name] || model.materials.add(name)
      m.color = Sketchup::Color.new(*COLORS[name])
      m
    end

    def self.pts(ring, z)
      ring.map { |x, y| Geom::Point3d.new(x.mm, y.mm, z.mm) }
    end

    # rings[0] = 외곽, rings[1..] = 구멍. dir: +1 위로, -1 아래로 돌출
    def self.extrude(ents, rings, z, h, dir)
      face = ents.add_face(pts(rings[0], z))
      return false unless face
      rings[1..-1].each do |hole|
        hf = ents.add_face(pts(hole, z))
        hf.erase! if hf && hf.valid?
      end
      face.reverse! if face.normal.z * dir < 0
      face.pushpull(h.mm)
      true
    rescue ArgumentError
      false
    end

    def self.run
      model = Sketchup.active_model
      model.start_operation('B1·1F·2F 모델링', true)
      fails = Hash.new(0)
      DATA.each do |fl, d|
        z = LEVELS[fl]
        fg = model.active_entities.add_group
        fg.name = fl
        layer = model.layers[fl] || model.layers.add(fl)
        fg.layer = layer
        [['슬래브', d['slab'], z, SLAB_T, -1],
         ['기둥',   d['cols'],  z, FLOOR_H - SLAB_T, 1],
         ['벽체',   d['walls'], z, FLOOR_H - SLAB_T, 1]].each do |name, polys, zz, h, dir|
          g = fg.entities.add_group
          g.name = "#{fl}_#{name}"
          g.material = material(model, name)
          polys.each do |rings|
            # 요소마다 하위 그룹으로 분리해서 서로 붙어 합쳐지지 않게 함
            eg = g.entities.add_group
            fails["#{fl} #{name}"] += 1 unless extrude(eg.entities, rings, zz, h, dir)
          end
        end
      end
      model.commit_operation
      model.active_view.zoom_extents
      msg = 'B1·1F·2F 슬래브/기둥/벽체 생성 완료'
      msg += "\n생성 실패: " + fails.map { |k, v| "#{k} #{v}개" }.join(', ') unless fails.empty?
      UI.messagebox(msg)
    rescue => err
      model.abort_operation
      UI.messagebox("오류: #{err.message}")
    end
  end
end

